    W = w; H = h; dpr = r; k = clamp(Math.min(W, 1.6 * H) / 1250, .72, 1.15); vs = clamp(Math.sqrt(W / 1200), .6, 1.1);
    if (keep) return;
    var n = Math.round(clamp(W * H / 9500, 50, 170)); P = [];
    for (var i = 0; i < n; i++) P.push(spawn({ g: i % 3, h: [] }, true));
    spray = []; wake = []; prevTc = null;
