  function geo() { var x0 = -.2 * W - 40 * k, x1 = 1.1 * W + 40 * k, v = (x1 - x0) / TX, t0 = (.40 * W - x0) / v; return { x0: x0, v: v, t0: t0, t1: t0 + JD, J: Math.min(.30 * H, 220 * k), L: 300 * k, R: .34 * 300 * k }; }
