  function start() { window.cancelAnimationFrame(raf); if (moving() && !document.hidden) { last = window.performance.now() / 1000; raf = window.requestAnimationFrame(frame); } else if (!moving()) eng.still(); }
  Object.keys(SRC).forEach(function (n) { left++; var im = new Image(); im.addEventListener('load', function () { if (--left === 0) { build(); start(); } }); im.src = SRC[n]; imgs[n] = im; });
  window.addEventListener('resize', function () { if (eng) size(); });
  window.addEventListener('scroll', function () { if (eng && sc && sc.follow && !moving()) { sc.scroll = window.scrollY || 0; eng.redraw(); } }, { passive: true });
